/// <summary>
/// CB705_VendorRebatePosting
/// Passing the rebateTransactionType to TAMRebatePostDateTransaction to disable customisation when not rebate management
/// </summary>
/// <returns><c>TAMRebatePostDateTransaction</c></returns>
protected TAMRebatePostDateTransaction createPostDateTransaction()
{
    TAMRebatePostDateTransaction postDateTransaction = next createPostDateTransaction();
    postDateTransaction.METParmRebateTransactionType(rebateTransactionType);
    return postDateTransaction;
}

/// <summary>
/// Bug 340401: E2E - RE-0013 Vendor Rebate - Current Batch Job Cannot Run Based on 'Lifetime'
/// If the posting date is not set, use today's date in the user time zone
/// </summary>
/// <param name = "_contract"><c>TAMRebatePostContract</c></param>
/// <returns><c>TAMRebatePost</c></returns>
protected static TAMRebatePost initRebatePostFromContract(TAMRebatePostContract _contract)
{
    // Bug 340352: [MS] E2E - RE-0031 Vendor Rebate - Batch Job Failed for Posting. MS SR# - 2603010030001346
    // If auto date population is selected, populate from date with today -7 days and to date with today
    if (_contract.metParmAutoSetDate())
    {
        utcdatetime utcNowTimeZoneOffset = DateTimeUtil::applyTimeZoneOffset(DateTimeUtil::utcNow(), DateTimeUtil::getUserPreferredTimeZone());
        ToDate endWeekDate = DateTimeUtil::date(utcNowTimeZoneOffset);
        FromDate startWeekDate = DateTimeUtil::date(DateTimeUtil::addDays(utcNowTimeZoneOffset, -6));

        _contract.parmFromDate(startWeekDate);
        _contract.parmToDate(endWeekDate);
    }

    TAMRebatePost rebatePost = next initRebatePostFromContract(_contract);

    if (rebatePost.parmTransDate() == dateNull())
    {
        rebatePost.parmTransDate(DateTimeUtil::date(DateTimeUtil::applyTimeZoneOffset(DateTimeUtil::utcNow(), DateTimeUtil::getUserPreferredTimeZone())));
    }        

    return rebatePost;
}

protected void processRebateTable()
{
    next processRebateTable();

    METProcMetrics procMetrics = METProcMetricsScope::current();

    if (procMetrics)
    {
        TAMRebateDeal rebateDeal = this.rebateDeal();

        if (rebateDeal)
        {
            procMetrics.incProcessedCountWithDocument(rebateDeal.Deal);
        }
    }
}
